#!/usr/bin/env bash
# Sauvegarde 1fichier BLONDIN EDITION v3.2 (GitHub) / Batocera 44
set -Eeuo pipefail
[[ "${EUID:-$(id -u)}" -eq 0 ]] || { echo '[ERREUR] Executer en root.' >&2; exit 1; }
for cmd in curl python3 bash; do command -v "$cmd" >/dev/null || { echo "[ERREUR] $cmd manquant." >&2; exit 1; }; done
WORK=$(mktemp -d /tmp/blondin-install-v32.XXXXXXXX)
trap 'rm -rf -- "$WORK"' EXIT
URL='https://raw.githubusercontent.com/blondin-svg/blondin.rep/b0e90ec6e392fcc7139eaa83aadc1c3fd3b57aed/Sauvegarde1fichier/1fichier-blondin-v3.1-CATEGORIES-MENUS-COMPLET.sh'
curl -fLsS --retry 3 --connect-timeout 20 "$URL" -o "$WORK/base.sh"
python3 - "$WORK/base.sh" "$WORK/install-v3.2.sh" <<'PY_GH_V32'
from pathlib import Path
import base64,hashlib,sys,zlib
source=Path(sys.argv[1]).read_bytes()
sha=hashlib.sha1(b'blob '+str(len(source)).encode()+b'\0'+source).hexdigest()
if sha!='5caeb368fc718e398a332c1e7dd7a30abca306df':
    raise SystemExit('[ERREUR] Source v3.1 GitHub modifiee. Installation refusee.')
stage=zlib.decompress(base64.b64decode('')).decode('utf-8')
stage=stage.replace("# Refuser que deux dossiers sources ecrivent au meme endroit lors d'un lot.","# Refuser toute collision distante, meme lors d'une sauvegarde individuelle.",1)
stage=stage.replace("replacement=\"        targets = [x['destination'].casefold() for x in selected]\\n        if len(set(targets)) != len(targets):\\n            raise RuntimeError('Deux systemes utilisent la meme categorie et le meme nom 1fichier. Renommer un systeme.')\\n\"+needle","replacement=\"        destinations = [x['destination'].casefold() for x in all_entries]\\n        if len(set(destinations)) != len(destinations):\\n            raise RuntimeError('Deux systemes utilisent la meme categorie et le meme nom 1fichier. Renommer un systeme.')\\n\"+needle",1)
stage=stage.replace("a=once(a,needle,replacement)\na+='\\n# '+MARK+' - moteur\\n'","a=once(a,needle,replacement)\n# Interdire le renvoi d'un media.zip laisse par une ancienne sauvegarde 1fichier.\n# Un ZIP repris doit provenir du meme job et du NOUVEAU chemin distant.\nneedle_retry=\"        remote_path(found['destination'])\\n        if not any(z['archive_job'] == archive_job\"\nreplacement_retry=\"        remote_path(found['destination'])\\n        if not any(h.get('mode') == 'copy' and h.get('id') == system_id and\\n                   h.get('job') == archive_job and h.get('destination') == found['destination']\\n                   for h in load_history() if isinstance(h, dict)):\\n            raise RuntimeError('Archive media issue de l ancien emplacement : refaire une sauvegarde complete.')\\n        if not any(z['archive_job'] == archive_job\"\na=once(a,needle_retry,replacement_retry)\nneedle_worker=\"        remote_path(found['destination'])\\n        notice('[{}] Reprise du media.zip\"\nreplacement_worker=\"        remote_path(found['destination'])\\n        if not any(h.get('mode') == 'copy' and h.get('id') == system_id and\\n                   h.get('job') == archive_job and h.get('destination') == found['destination']\\n                   for h in load_history() if isinstance(h, dict)):\\n            raise RuntimeError('Archive media provenant d une ancienne destination.')\\n        notice('[{}] Reprise du media.zip\"\na=once(a,needle_worker,replacement_worker)\na+='\\n# '+MARK+' - moteur\\n'",1)
if 'needle_worker=' not in stage: raise SystemExit('[ERREUR] Correctif v3.2 incomplet.')
needle=b'\nPY_SUBMENU\n\n'
if source.count(needle)!=1: raise SystemExit('[ERREUR] Source GitHub v3.1 incompatible.')
source=source.replace(needle,needle+stage.encode('utf-8')+b'\n',1)
source=source.replace(b'# Batocera 44 / v3.1 CATEGORIES + SOUS-MENUS (Batocera + Mobile)',b'# Batocera 44 / v3.2 DOSSIERS REELS 1FICHIER (Batocera + Mobile)',1)
source=source.replace(b'  1FICHIER-BLONDIN-V3.1 / BATOCERA 44 + MOBILE',b'  1FICHIER-BLONDIN-V3.2 / BATOCERA 44 + MOBILE',1)
source=source.replace(b"echo '[OK] v3.1 : sauvegarde, media.zip, categories Consoles/Ordinateurs/Arcade et Web.'",b"echo '[OK] v3.2 : sauvegardes dans Sauvegarde Batocera/{Consoles,Ordinateurs,Arcade}/systeme et Web.'",1)
out=Path(sys.argv[2]);out.write_bytes(source);out.chmod(0o700)
print('[OK] Installateur complet v3.2 prepare.')
PY_GH_V32
bash -n "$WORK/install-v3.2.sh"
bash "$WORK/install-v3.2.sh"
